   \label{eq_P37}
 \geq \frac{\Delta t}{2}   \Vert \partial_t^\Theta u \Vert_{Q^{h}}^2 \!-\! C_{\ref{lemma_P37}} \stdnorm{u}_j^2 


 \nonumber
