  We define $U := \bar\Pi(\Delta t \partial_t^\Theta u)$ and with 
$ J(u, U) = 0 $ we see 
\begin{align*}
(B_h+J)(u, \tilde\Pi(\Delta t \partial_t^\Theta u)) 
= 
\underbrace{B_h(u, \Delta t \partial_t^\Theta u)}_{\point{1}} + \underbrace{J(u, \Delta t \partial_t^\Theta u)}_{\point{2}} - \underbrace{B_h(u,U)}_{\point{3}}.
\end{align*}
We will bound the three r.h.s. terms from below one after the other. \\[-1.2ex]

\noindent \underline{Term \tpoint{1}: $B_h(u, \Delta t \partial_t^\Theta u)$}\\
 We start by writing out $B_h(u, \Delta t \partial_t^\Theta u)$:
 \begin{align*}
  B_h(u, \Delta t \partial_t^\Theta u) = & (\partial_t u, \Delta t \partial_t^\Theta u)_{Q^{h}}
   +  (\vec{w} \cdot \nabla u, \Delta t \partial_t^\Theta u)_{Q^{h}} + (\nabla u, \Delta t \nabla \partial_t^\Theta u)_{Q^{h}} \\
  & + \sum_{n=1}^{N-1} \Delta t (\jump{u}^n, (\partial_t^\Theta u)^n_+)_{\Omega^{h}(t_n)} + \Delta t (u^0_+, ( \partial_t^\Theta u)^0_+)_{\Omega^{h}(0)}
 \end{align*}
 From \Cref{def_mesh_deriv}, we obtain $\partial_t u = \partial_t^{\Theta} u - \underbrace{(\partial_t \Theta_h^{\text{st}} \circ (\Theta_h^{\text{st}})^{-1})}_{=: \tilde w} \cdot \nabla u$, leading to
 \begin{align*}
  B_h(u, & \Delta t \partial_t^\Theta u) - \Delta t \Vert \partial_t^\Theta u\Vert_{Q^{h}}^2 = \underbrace{ ( (\vec{w} - \tilde w) \cdot \nabla u, \Delta t \partial_t^\Theta u)_{Q^{h}}}_{\point{a}} \\
  & + \underbrace{\textstyle\sum_{n=1}^{N-1} \Delta t (\jump{u}^n, (\partial_t^\Theta u)^n_+)_{\Omega^{h}(t_n)} + \Delta t (u^0_+, ( \partial_t^\Theta u)^0_+)_{\Omega^{h}(0)}}_{\point{b}} 
   + \underbrace{ (\nabla u, \Delta t \nabla \partial_t^\Theta u)_{Q^{h}}}_{\point{c}}
 \end{align*}
 All those terms will now be estimated seperately. In general, we apply a combination of Cauchy-Schwarz and Youngs inequality, combined with several previous results. We start with $\tpoint{a}$:
 \begin{align*}
  \tpoint{a} &= \sum_{n=1}^N ( (\vec{w} - \tilde w) \cdot \nabla u, \Delta t \partial_t^\Theta u)_{Q^{h\scalebox{0.3}{\!},\scalebox{0.3}{\!}n}}
  \leq 2 \Delta t \Vert (\vec{w} - \tilde w) \cdot \nabla u\Vert_{Q^{h}}^2 + \frac{\Delta t}{8} \Vert \partial_t^\Theta u\Vert_{Q^{h}}^2 \\
  &\leq 2 \Delta t \|(\vec{w} - \tilde w)\|_\infty^2 \Vert\nabla u \Vert_{Q^{h}}^2 + \frac{\Delta t}{8} \Vert \partial_t^\Theta u \Vert_{Q^{h}}^2 \leq C_{\point{a}} \Delta t \stdnorm{u}^2 + \frac{\Delta t}{8} \Vert \partial_t^\Theta u \Vert_{Q^{h}}^2
 \end{align*}
 where we set $C_{\point{a}} = 2 \|(\vec{w} - \tilde w)\|_\infty^2$ which is bounded uniformly in $h$ and $\Delta t$.

 Next, we continue with $\tpoint{b}$ applying Cauchy-Schwarz and Young's inequality:
 \begin{align*}
  \tpoint{b}

  &\leq 2 C_{\ref{lemma_bound_tn_ag_temporal_vol}} \tripplejump{u}^2 + \frac{\Delta t^2}{8 C_{\ref{lemma_bound_tn_ag_temporal_vol}}} \sum_{n=1}^N \Vert (\partial_t^\Theta u)^{n-1}_+ \Vert_{\Omega^{h}(t_{n-1})}^2
\end{align*}
For the sum, we exploit $\partial_t^\Theta u \in W_h$ and apply \cref{lemma_bound_tn_ag_temporal_vol} and \cref{lemP35} where we make use of Assumption \ref{h2lesssimDeltat} to bound $h^2 \leq C_G \Delta t$:
\begin{align}
  \Delta t^2 \sum_{n=1}^N & \Vert (\partial_t^\Theta u)^{n-1}_+ \Vert_{\Omega^{h}(t_{n-1})}^2
   \overset{\cref{eq_bound_tn_ag_temporal_vol}}{\leq} C_{\ref{lemma_bound_tn_ag_temporal_vol}} \cdot \Delta t \left( \Vert \partial_t^\Theta u \Vert_{Q^{h}}^2 + \frac{h^2}{\gamma_J} \tripplenorm{\partial_t^\Theta u}_J^2 \right) \nonumber \\

  &\overset{\!\!\!\!\cref{eq_lemP35}\!\!\!\!}{\leq} C_{\ref{lemma_bound_tn_ag_temporal_vol}}\left( C_{\ref{lemP35}} C_G \left\{ \gamma_J^{-1} \tripplenorm{u}_J^2 + (h+\Delta t)\| \nabla u \|_{Q^h}^2 \right\} + \Delta t \Vert \partial_t^\Theta u \Vert_{Q^h}^2\right) \label{eq:interm}\\
  \intertext{ which yields with $C_{\point{b}} := \max\{2 C_{\ref{lemma_bound_tn_ag_temporal_vol}}, \frac18 C_{\ref{lemP35}} C_G \cdot \max\{\gamma_J^{-1}, h+\Delta t\} \}$, which is bounded uniformly in $h$ and $\Delta t$, the estimate for the term \tpoint{b}}
  \Rightarrow \tpoint{b} & \leq C_{\point{b}} \stdnorm{u}_j^2 + \frac{\Delta t}{8} \Vert \partial_t^\Theta u \Vert_{Q^{h}}^2
 \end{align}
 We estimate $\tpoint{c}$ applying Cauchy-Schwarz and Young's inequality with $\epsilon = \sqrt{C_{\ref{lemma_temporal_inverse_ineq_gp}}}$:
 \begin{align*}
  &\tpoint{c} = (\nabla u, \Delta t \nabla \partial_t^\Theta u)_{Q^{h}} 
   \overset{\cref{eq_temporal_inverse_ineq_gp}}{\leq} \frac{\epsilon}{2} \Vert \nabla u \Vert^2_{Q^h} + \frac{C_{\ref{lemma_temporal_inverse_ineq_gp}}}{2 \epsilon} \Big( \| \nabla u \|_{Q^{h}}^2 + \frac{1}{\gamma_J} \tripplenorm{u}_J^2 \Big) 

   \leq C_{\point{c}} 
   \stdnorm{u}_j^2


 \end{align*}
 with $C_{\point{c}} = \sqrt{C_{\ref{lemma_temporal_inverse_ineq_gp}}} \cdot \max \{1, \frac{1}{2 \gamma_J}\}$ independent of $h$ and $\Delta t$.
Putting the estimates for $\tpoint{a}$, $\tpoint{b}$ and $\tpoint{c}$ together, we obtain
$$
B_h(u,\Delta t \partial_t^{\Theta}u) \geq \frac34 \Delta t \Vert \partial_t^{\Theta} u \Vert_{Q^h}^2 - C_{\point{1}} \stdnorm{u}_j^2
$$
with $C_{\point{1}} := C_{\point{a}} \Delta t + C_{\point{b}} + C_{\point{c}}$ which is uniformly bounded in $h$ and $\Delta t$.\\[-1.2ex]

\noindent \underline{Term \tpoint{2}: $J(u, \Delta t \partial_t^\Theta u)$}\\
Next, we consider the GP term applying \Cref{lemP35}, Cauchy-Schwarz and a Young's inequality with $\beta := \sqrt{C_{\ref{lemP35}}}$ (s.t. $C_{\ref{lemP35}} / \beta= \beta$):
 \begin{align*}
  J(u,& \Delta t \partial_t^\Theta u) \geq - \frac{\beta}{2} \tripplenorm{u}_J^2 - \frac{\Delta t^2}{2 \beta} \tripplenorm{\partial_t^\Theta u}_J^2
  \\ &
   \overset{\cref{eq_lemP35}}{\geq} - \frac{\beta}{2} \tripplenorm{u}_J^2 - \frac{C_{\ref{lemP35}}}{2 \beta} \tripplenorm{u}_J^2 - \frac{C_{\ref{lemP35}}}{\beta} \frac{\gamma_J (h + \Delta t)}{2} \| \nabla u \|_{Q^h}^2 



  \geq - C_{\point{2}} \stdnorm{u}_j^2.
 \end{align*}
 with $C_{\point{2}} := \beta \cdot \max\{1, \gamma_J (h + \Delta t)/2\}$.\\[-1.2ex]


\noindent \underline{Term \tpoint{3}: $B_h(u,U)$} \\
Applying \Cref{lemma_B_Bmc_diff} and a Cauchy-Schwarz inequality we obtain
 \begin{align*}
   B_h(u,U) 
  \leq  B_{mc}(u, U) + C_{\ref{lemma_B_Bmc_diff}} \cdot (h^{q_s} + \Delta t^{q_t}) \cdot 
  \textstyle \Big( \int_0^T \Vert u \Vert_{\partial \Omega^h(t)}^2 \mathrm{d}t 
  \Big)^{\frac12} \Big(
  \int_0^T \Vert U \Vert_{\partial \Omega^h(t)}^2 \mathrm{d}t \Big)^{\frac12}.
 \end{align*}
 For $B_{mc}(u, U)$, we note that $U$ is a slice-wise constant function in both space and time, hence the summands involving $\nabla U$ and $\partial_t U$ vanish and we obtain
 \begin{align*}
  B_{mc}(u, U) 
  = \sum_{n=1}^{N-1} (u^n_-, [ \bar\Pi(\Delta t \partial_t^\Theta u) ]^n )_{\Omega^h(t_n)} 
  + (u^N_-, \bar\Pi(\Delta t \partial_t^\Theta u)_-^N  
  )_{\Omega^h(T^-)} = 0
 \end{align*}
