\!=\! \sum_{n=1}^{N} \!\Big(\! \fint_{\Omega^h(t_n)} \!\!\!\!\! (\Delta t \partial_t^\Theta u)_-^n \, \mathrm{d}x \!\Big)^2\! \int_{I_n} \Vert 1_{I_n} \Vert_{\partial \Omega^h(t)}^2 \mathrm{d}t \\
& \!\leq\! \sum_{n=1}^N \!\Vert (\Delta t \partial_t^\Theta u)_-^n \Vert_{\Omega^{h}\!(t_{n\!})}^2 
\! \int_{I_n}\!\!\! \frac{|\partial \Omega^h(t)|}{|\Omega^h(t_n)|} \mathrm{d}t  \!\stackrel{\!\!\!\!\text{Ass.}\ref{ass:COmega}\!\!\!\!}{\leq}\! C_\Omega \!\sum_{n=1}^N \!\Delta t^3 \Vert (\partial_t^\Theta \!u)_-^n \Vert_{\Omega^{h}\!(t_{n\!})}^2 
\!\! \leq \! C_\Omega C_{\!\eqref{eq:interm}} \Delta t \tripplenorm{u}^2 \!
\end{align*}
where in the last step applied an estimate as in \eqref{eq:interm} again, but bounded directly (slightly cruder) by $\tripplenorm{u}^2$.
Finally, we have with $C_{\point{3}} = \frac12 C_{\ref{lemma_B_Bmc_diff}} (
C_{\ref{stra_ineq_stronger}} + C_\Omega C_{\eqref{eq:interm}}
)$

$$
- B_h(u,U) \geq - C_{\point{3}} (h^{q_s} + \Delta t^{q_t}) \Delta t^{\frac12} 
  (\stdnorm{u}^2 + \Delta t \Vert \partial_t^\Theta u \Vert_{Q^{h}}^2)
$$

