   \Pi^n_W\colon L^2 (Q^{\text{lin}\scalebox{0.3}{\!},\scalebox{0.3}{\!}n}_{\mathcal{E}}) \to W_{h, \text{cut}}^{n,k}(Q^{\text{lin}\scalebox{0.3}{\!},\scalebox{0.3}{\!}n}_{\mathcal{E}}), 
