   \\
   \| \nabla \hat e_u \|_{Q^{\text{lin}\scalebox{0.3}{\!},\scalebox{0.3}{\!}n}_{\mathcal{E}}} 
   &
   \!\lesssim \! \Delta t^{\ell_t\hphantom{-1}} \|\hat u \|_{\Hrs{1}{\ell_t}(Q^{\text{lin}\scalebox{0.3}{\!},\scalebox{0.3}{\!}n}_{\mathcal{E}})} \!\!+\!\! \hphantom{\Delta t^{-\frac12}}h^{\ell_{s\!}-1\!} \| \hat u\|_{\Hrs{\ell_s}{0}(Q^{\text{lin}\scalebox{0.3}{\!},\scalebox{0.3}{\!}n}_{\mathcal{E}})}\text{ if } \ell_s \!\ge\! 2, \!\!
   \\
   \!\!\!\!\!\!\!\!\!\!  \| \hat e_u\!(\cdot,t_n\!)\! \|_{\Omega^{\text{lin}\scalebox{0.3}{\!},\scalebox{0.5}{\!}I_{\scalebox{0.45}{\!n}}}_{\mathcal{E}}} 
